"""Rebuild docs/activity/<YYYY-MM>.jsonl from the local Claude Code session store.

The Stop/SessionEnd hook (`templates/base/hooks/harness-activity.mjs`) writes the
activity feed going forward, one upserted record per command invocation. Sessions
captured BEFORE the upsert fix carry duplicate / cumulative-growth rows and no
`cmd_ts` key, so they cannot be deduped after the fact.

This module re-derives the activity feed straight from the session transcripts at
`~/.claude/projects/<slug>/*.jsonl`, emitting exactly one correct record per
command invocation. The per-invocation extraction MIRRORS the .mjs hook's
algorithm (file/line/rejection accounting, intervention counting, outcome rules);
keep the two in sync — the hook + backfill unit tests encode the same expected
numbers to catch drift.

Pure functions where practical: `extract_invocations` takes already-parsed events
and returns record dicts. `backfill_activity` is the I/O orchestrator.
"""

from __future__ import annotations

import json
import re
import subprocess
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

# Command detection — Claude Code wraps invocations as
# `<command-name>/arh-init</command-name>`; a plain `/cmd` typed at line start
# is the fallback. Mirrors detectCommand() in harness-activity.mjs.
_XML_CMD = re.compile(r"<command-name>/([\w:-]+)</command-name>")
_PLAIN_CMD = re.compile(r"^/([\w:-]+)(?:\s|$)")
_FEATURE = re.compile(r"([A-Z]{2,}-\d+)")


# ---- pure extraction ------------------------------------------------------


def _user_text(ev: dict) -> str:
    c = (ev.get("message") or {}).get("content")
    if isinstance(c, str):
        return c
    if isinstance(c, list):
        return "\n".join(
            b.get("text", "")
            for b in c
            if isinstance(b, dict) and b.get("type") == "text" and isinstance(b.get("text"), str)
        )
    return ""


def _has_tool_result(ev: dict) -> bool:
    c = (ev.get("message") or {}).get("content")
    return isinstance(c, list) and any(
        isinstance(b, dict) and b.get("type") == "tool_result" for b in c
    )


def _detect_command(text: str) -> str | None:
    if not text:
        return None
    m = _XML_CMD.search(text)
    if m:
        return "/" + m.group(1)
    m = _PLAIN_CMD.match(text.strip())
    if m:
        return "/" + m.group(1)
    return None


def _ts(ev: dict) -> str | None:
    return ev.get("timestamp") or (ev.get("message") or {}).get("timestamp")


def _content_blocks(ev: dict) -> list[dict]:
    c = (ev.get("message") or {}).get("content")
    return c if isinstance(c, list) else []


def extract_invocations(
    events: list[dict],
    *,
    user: str,
    session_id: str,
    subagent_events: list[dict] | None = None,
) -> list[dict]:
    """Return one activity record per command invocation found in `events`.

    An invocation spans [command-event, next-command-event) — the same window
    the live hook's final Stop captured before the next command was typed.

    `subagent_events` are the flattened transcripts from
    `<session>/subagents/*.jsonl`. Commands like /arh-implement delegate file edits
    to subagents, so those Write/Edit/tool_result blocks live OUTSIDE the main
    transcript. Each subagent event is attributed to the invocation whose time
    window [cmd_ts, next_cmd_ts) contains its timestamp.
    """
    subagent_events = subagent_events or []
    cmd_indices = [
        i
        for i, ev in enumerate(events)
        if ev.get("type") == "user" and _detect_command(_user_text(ev))
    ]

    # Subagent token attribution: a subagent keeps streaming while the user
    # types the next command, so lines of ONE message can land on both sides of
    # an invocation boundary. Per-line window attribution would count that
    # message's usage in BOTH invocations. Attribute each message to the window
    # containing its FIRST line — the invocation that spawned it — and keep the
    # LAST usage snapshot (final cumulative totals).
    win_bounds: list[tuple[float | None, float]] = []
    for k, start in enumerate(cmd_indices):
        ws = _event_ms(events[start])
        nxt = _event_ms(events[cmd_indices[k + 1]]) if k + 1 < len(cmd_indices) else None
        win_bounds.append((ws, nxt if nxt is not None else float("inf")))
    sub_first_ms: dict[str, float] = {}
    sub_last_usage: dict[str, tuple[str | None, dict[str, Any]]] = {}  # mid -> (model, usage)
    for se in subagent_events:
        if se.get("type") != "assistant":
            continue
        smsg = se.get("message") or {}
        su = smsg.get("usage")
        smid = smsg.get("id") or se.get("requestId")
        if not isinstance(su, dict) or not smid:
            continue
        sms = _event_ms(se)
        if sms is not None and (smid not in sub_first_ms or sms < sub_first_ms[smid]):
            sub_first_ms[smid] = sms
        sub_last_usage[smid] = (smsg.get("model"), su)
    sub_usage_by_window: dict[int, dict[str, tuple[str | None, dict[str, Any]]]] = {}
    for smid, fms in sub_first_ms.items():
        for k, (ws, we) in enumerate(win_bounds):
            if ws is not None and ws <= fms < we:
                sub_usage_by_window.setdefault(k, {})[smid] = sub_last_usage[smid]
                break

    records: list[dict] = []
    for k, start in enumerate(cmd_indices):
        end = cmd_indices[k + 1] if k + 1 < len(cmd_indices) else len(events)
        span = events[start:end]
        cmd_ev = events[start]
        command = _detect_command(_user_text(cmd_ev))
        cmd_ts = _ts(cmd_ev)
        if not cmd_ts:
            continue  # cannot key without an invocation timestamp

        # Time window for subagent attribution: [cmd_ts, next_cmd_ts).
        win_start = _event_ms(cmd_ev)
        next_cmd_ts = _ts(events[cmd_indices[k + 1]]) if k + 1 < len(cmd_indices) else None
        win_end = _ms(next_cmd_ts) if next_cmd_ts else float("inf")
        if win_start is None:
            sub_in_window: list[dict] = []
        else:
            sub_in_window = [
                se
                for se in subagent_events
                if (m := _event_ms(se)) is not None and win_start <= m < win_end
            ]
        # Combined, time-ordered stream for code-change accounting.
        code_events = sorted(
            list(span) + sub_in_window,
            key=lambda e: (_event_ms(e) if _event_ms(e) is not None else (win_start or 0)),
        )

        feature = None
        fm = _FEATURE.search(_user_text(cmd_ev))
        if fm:
            feature = fm.group(1)

        # interventions: free-text user messages after an assistant turn
        intervention_count = 0
        last_was_assistant = False
        for ev in span[1:]:
            t = ev.get("type")
            if t == "assistant":
                last_was_assistant = True
            elif (
                t == "user"
                and last_was_assistant
                and _user_text(ev).strip()
                and not _has_tool_result(ev)
            ):
                intervention_count += 1
                last_was_assistant = False

        # duration: command ts → latest ts in span
        duration_s = 0
        end_ts = None
        for ev in reversed(span):
            end_ts = _ts(ev)
            if end_ts:
                break
        if end_ts:
            try:
                s = _parse_ms(cmd_ts)
                e = _parse_ms(end_ts)
                if e > s:
                    duration_s = round((e - s) / 1000)
            except (ValueError, TypeError):
                duration_s = 0

        # token usage — mirror harness-activity.mjs. The transcript writes one
        # line per content block, each repeating the same message.id and usage;
        # dedupe by message.id (last line wins) or every block double-counts.
        # Main-transcript usage comes from this span; subagent usage from the
        # first-line-window attribution computed above.
        usage_by_id: dict[str, tuple[str | None, dict[str, Any]]] = {}  # mid -> (model, usage)
        for ev in span:
            if ev.get("type") != "assistant":
                continue
            msg = ev.get("message") or {}
            u = msg.get("usage")
            if not isinstance(u, dict):
                continue
            mid = msg.get("id") or ev.get("requestId")
            if not mid:
                continue
            usage_by_id[mid] = (msg.get("model"), u)
        usage_by_id.update(sub_usage_by_window.get(k, {}))

        # Per-model aggregation — cost depends on model + cache-write TTL
        # (5m writes bill 1.25x input price, 1h writes 2x). The TTL split lives
        # in usage.cache_creation.{ephemeral_1h,_5m}; when absent, the
        # cache_creation_input_tokens total is attributed to 5m.
        models: dict[str, dict[str, int]] = {}
        for model, u in usage_by_id.values():
            agg = models.setdefault(
                model or "unknown",
                {"input": 0, "output": 0, "cache_read": 0, "cache_write_5m": 0, "cache_write_1h": 0},
            )
            agg["input"] += int(u.get("input_tokens") or 0)
            agg["output"] += int(u.get("output_tokens") or 0)
            agg["cache_read"] += int(u.get("cache_read_input_tokens") or 0)
            cc = u.get("cache_creation")
            if isinstance(cc, dict):
                agg["cache_write_1h"] += int(cc.get("ephemeral_1h_input_tokens") or 0)
                agg["cache_write_5m"] += int(cc.get("ephemeral_5m_input_tokens") or 0)
            else:
                agg["cache_write_5m"] += int(u.get("cache_creation_input_tokens") or 0)

        input_token = sum(a["input"] for a in models.values())
        output_token = sum(a["output"] for a in models.values())
        cache_read = sum(a["cache_read"] for a in models.values())
        cache_write = sum(a["cache_write_5m"] + a["cache_write_1h"] for a in models.values())

        # code-change metrics — mirror harness-activity.mjs
        files_created: set[str] = set()
        files_modified: set[str] = set()
        lines_added = 0
        tool_rejections = 0
        tool_use_files: dict[str, str] = {}
        tool_use_lines: dict[str, int] = {}
        for ev in code_events:
            for c in _content_blocks(ev):
                if c.get("type") == "tool_use":
                    name = c.get("name")
                    cid = c.get("id")
                    inp = c.get("input") or {}
                    fp = inp.get("file_path") or inp.get("path")
                    if fp and cid:
                        tool_use_files[cid] = fp
                    delta = 0
                    if name == "Write" and fp:
                        files_created.add(fp)
                        txt = inp.get("content") or ""
                        if isinstance(txt, str):
                            delta = len(txt.split("\n"))
                    elif name == "Edit" and fp:
                        files_modified.add(fp)
                        ns, os_ = inp.get("new_string") or "", inp.get("old_string") or ""
                        if isinstance(ns, str) and isinstance(os_, str):
                            d = len(ns.split("\n")) - len(os_.split("\n"))
                            if d > 0:
                                delta = d
                    elif name == "MultiEdit" and fp:
                        files_modified.add(fp)
                        for e in inp.get("edits") or []:
                            ns, os_ = e.get("new_string") or "", e.get("old_string") or ""
                            if isinstance(ns, str) and isinstance(os_, str):
                                d = len(ns.split("\n")) - len(os_.split("\n"))
                                if d > 0:
                                    delta += d
                    if delta > 0 and cid:
                        lines_added += delta
                        tool_use_lines[cid] = delta
                elif c.get("type") == "tool_result" and c.get("is_error") is True:
                    tool_rejections += 1
                    tid = c.get("tool_use_id")
                    fp = tool_use_files.get(tid)
                    if fp:
                        files_created.discard(fp)
                        files_modified.discard(fp)
                    lines_added -= tool_use_lines.get(tid, 0)
        if lines_added < 0:
            lines_added = 0

        # outcome: aborted when no assistant turn ran; else completed, upgraded
        # to error on a recent failed tool_result (last 10 events of the span).
        had_assistant = any(ev.get("type") == "assistant" for ev in span[1:])
        outcome = "completed" if had_assistant else "aborted"
        for ev in span[-10:]:
            if any(
                c.get("type") == "tool_result" and c.get("is_error") is True
                for c in _content_blocks(ev)
            ):
                outcome = "error"
                break

        records.append(
            {
                "ts": cmd_ts,
                "user": user,
                "session_id": session_id,
                "cmd_ts": cmd_ts,
                "kind": "command",
                "command": command,
                "feature": feature,
                "duration_s": duration_s,
                "outcome": outcome,
                "intervention_count": intervention_count,
                "files_created": len(files_created),
                "files_modified": len(files_modified),
                "lines_added": lines_added,
                "tool_rejections": tool_rejections,
                "input_token": input_token,
                "output_token": output_token,
                "cache_read": cache_read,
                "cache_write": cache_write,
                "total": input_token + output_token + cache_read + cache_write,
                "models": models,
            }
        )
    return records


# ---- I/O orchestration ----------------------------------------------------


@dataclass
class BackfillResult:
    sessions_scanned: int = 0
    invocations: int = 0
    rows_before: int = 0
    rows_after: int = 0
    preserved_other_sessions: int = 0
    months_written: list[str] = field(default_factory=list)
    wrote: bool = False


def slug_for(path: Path) -> str:
    """Claude Code project-dir slug. Matches commands.analyse._slug_for."""
    s = str(path).lstrip("/")
    return "-" + s.replace("/", "-").replace(".", "-").replace(" ", "-")


def _parse_ms(iso: str) -> float:
    from datetime import datetime

    return datetime.fromisoformat(iso.replace("Z", "+00:00")).timestamp() * 1000


def _ms(iso: str | None) -> float | None:
    """Parse an ISO timestamp to epoch-ms; None on failure/empty."""
    if not iso:
        return None
    try:
        return _parse_ms(iso)
    except (ValueError, TypeError):
        return None


def _event_ms(ev: dict) -> float | None:
    """Epoch-ms of an event's timestamp (top-level or message.timestamp)."""
    return _ms(_ts(ev))


def _read_jsonl(path: Path) -> list[dict]:
    out: list[dict] = []
    try:
        text = path.read_text(encoding="utf-8")
    except OSError:
        return out
    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            out.append(json.loads(line))
        except json.JSONDecodeError:
            continue
    return out


def _session_id_of(events: list[dict], fallback: str) -> str:
    for ev in events:
        sid = ev.get("sessionId")
        if sid:
            return sid
    return fallback


def _git_email(root: Path) -> str:
    try:
        out = subprocess.run(
            ["git", "config", "user.email"],
            cwd=root,
            capture_output=True,
            text=True,
            check=False,
        )
        email = out.stdout.strip().lower()
        return email or "unknown"
    except OSError:
        return "unknown"


def _month_of(iso: str) -> str:
    from datetime import UTC, datetime

    try:
        d = datetime.fromisoformat(iso.replace("Z", "+00:00"))
    except (ValueError, TypeError):
        d = datetime.now(UTC)
    return f"{d.year:04d}-{d.month:02d}"


def backfill_activity(
    root: Path,
    *,
    sessions_root: Path | None = None,
    dry_run: bool = False,
    user: str | None = None,
) -> BackfillResult:
    """Rebuild docs/activity/*.jsonl under `root` from the session store.

    Rows for sessions we can re-derive are replaced; rows for unknown sessions
    (e.g. teammates' committed history) are preserved verbatim.
    """
    sessions_root = sessions_root or (Path.home() / ".claude" / "projects")
    user = user or _git_email(root)
    sdir = sessions_root / slug_for(root)
    session_files = sorted(sdir.glob("*.jsonl")) if sdir.is_dir() else []

    new_records: list[dict] = []
    rebuilt_sids: set[str] = set()
    for f in session_files:
        events = _read_jsonl(f)
        if not events:
            continue
        sid = _session_id_of(events, f.stem)
        # Subagent transcripts live at <session>/subagents/*.jsonl — file edits
        # delegated to agents (e.g. /arh-implement) are recorded there, not in main.
        sub_events: list[dict] = []
        sub_dir = f.with_suffix("") / "subagents"
        if sub_dir.is_dir():
            for sf in sorted(sub_dir.glob("*.jsonl")):
                sub_events.extend(_read_jsonl(sf))
        recs = extract_invocations(
            events, user=user, session_id=sid, subagent_events=sub_events
        )
        if recs:
            rebuilt_sids.add(sid)
            new_records.extend(recs)

    activity_dir = root / "docs" / "activity"
    existing_files = sorted(activity_dir.glob("*.jsonl")) if activity_dir.is_dir() else []
    existing_rows: list[dict] = []
    for f in existing_files:
        existing_rows.extend(_read_jsonl(f))

    preserved = [r for r in existing_rows if r.get("session_id") not in rebuilt_sids]
    final_rows = preserved + new_records

    result = BackfillResult(
        sessions_scanned=len(session_files),
        invocations=len(new_records),
        rows_before=len(existing_rows),
        rows_after=len(final_rows),
        preserved_other_sessions=len(preserved),
    )

    # regroup by month and sort by ts within each month
    by_month: dict[str, list[dict]] = {}
    for r in final_rows:
        key = r.get("cmd_ts") or r.get("ts") or ""
        by_month.setdefault(_month_of(key), []).append(r)
    for rows in by_month.values():
        rows.sort(key=lambda r: r.get("ts") or "")
    result.months_written = sorted(by_month.keys())

    if dry_run:
        return result

    activity_dir.mkdir(parents=True, exist_ok=True)
    # rewrite every month that has rows; remove month files emptied by the rebuild
    keep = set(by_month.keys())
    for f in existing_files:
        if f.stem not in keep:
            f.unlink(missing_ok=True)
    for month, rows in by_month.items():
        body = "\n".join(json.dumps(r) for r in rows) + "\n"
        (activity_dir / f"{month}.jsonl").write_text(body, encoding="utf-8")
    result.wrote = True
    return result
